        g.toggle_flag(0, 0)
        g.toggle_flag(1, 1)
        self.assertEqual(g.flags_remaining(), 1)

    def test_adjacent_mine_count(self):
        g = Game(width=3, height=3, mines=8, rng=random.Random(1))
        g._place_mines(safe=(1, 1))
        self.assertEqual(g.cells[g.index(1, 1)].adjacent, 8)

    def test_revealing_mine_loses(self):
        g = Game(width=2, height=2, mines=1, rng=random.Random(0))
        # Find a mine cell by placing mines with a faraway safe corner.
        for seed in range(100):
            g = Game(width=2, height=2, mines=1, rng=random.Random(seed))
            g.reveal(0, 0)
            if not g.lost:
                break
        # The other cell must hold the mine (single mine game).
        self.assertEqual(sum(1 for c in g.cells if c.mine), 1)
        mine_idx = next(i for i, c in enumerate(g.cells) if c.mine)
        g.reveal(mine_idx % 2, mine_idx // 2) if not g.won else None
        # Guard: if 0,0 was empty, the game may not be lost yet.
        if not g.won:
            self.assertTrue(g.lost)


class VictoryTest(unittest.TestCase):
    def test_win_when_all_safe_revealed(self):
        g = Game(width=3, height=3, mines=1, rng=random.Random(7))
        # Reveal every non-mine forever until won/lost.
        for y in range(3):
            for x in range(3):
                g.reveal(x, y)
        if g.lost:
            # Retry with different mine layout (single mine, avoid corner).
            g = Game(width=3, height=3, mines=1, rng=random.Random(999))
            for y in range(3):
                for x in range(3):
                    if g.cells[g.index(x, y)].mine:
                        continue
                    g.reveal(x, y)
            self.assertTrue(g.won)
        else:
            self.assertTrue(g.won)


